def crr_pure(S, K, r, sigma, T, n, kind="call"):
    """A European CRR tree in pure Python (level 2 builds it)."""
    dt = T / n
    u = exp(sigma * sqrt(dt))
    d = 1 / u
    p = (exp(r * dt) - d) / (u - d)
    disc = exp(-r * dt)
    sign = 1 if kind == "call" else -1
    v = [max(sign * (S * u ** (2 * j - n) - K), 0.0) for j in range(n + 1)]
    for i in range(n, 0, -1):
        v = [disc * (p * v[j + 1] + (1 - p) * v[j]) for j in range(i)]
    return v[0]

